    addQ(3, 14, 2, 'Türkiye\'de genel seçimler kural olarak kaç yılda bir ve hangi organın seçimleriyle birlikte yapılır?', '5 yılda bir - TBMM ve Cumhurbaşkanlığı seçimleri birlikte', '4 yılda bir', '3 yılda bir', '6 yılda bir', '2 yılda bir', 'A', '2017 değişikliğiyle TBMM ve Cumhurbaşkanlığı seçimleri 5 yılda bir aynı gün yapılır.');
    addQ(3, 14, 2, 'Seçimlerde oy kullanma hakkı bakımından aşağıdakilerden hangisi oy kullanamaz?', 'Silah altında bulunan er ve erbaşlar ile askeri öğrenciler', 'Tutuklular', 'Yurt dışındaki Türk vatandaşları', 'Memurlar', '18 yaşını dolduran üniversite öğrencileri', 'A', 'Er ve erbaşlar, askeri öğrenciler ve taksirli suçlar hariç cezaevindeki hükümlüler oy kullanamaz.');

    // Level 3: Zor & Detay
    addQ(3, 14, 3, 'Anayasa değişiklik teklifi TBMM üye tamsayısının en az kaçta kaçı tarafından yazılı olarak verilebilir?', 'En az 1/3 (200 milletvekili)', '1/2', '3/5', '2/3', '1/10', 'A', 'Anayasa değişikliği teklifi için TBMM üye tamsayısının (600) en az 1/3\'ünün (200 vekil) yazılı teklifi şarttır.');
